#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

extern void dgeev_(char *jobvl, char *jobvr, int *n, double *a, int *lda,
                   double *wr, double *wi, double *vl, int *ldvl,
                   double *vr, int *ldvr, double *work, int *lwork,
                   int *info, size_t jobvl_len, size_t jobvr_len);

static PyObject *
dominant_eigen(PyObject *self, PyObject *arg)
{
    PyArrayObject *arr = (PyArrayObject *)PyArray_FROM_OTF(
        arg, NPY_DOUBLE, NPY_ARRAY_ALIGNED | NPY_ARRAY_C_CONTIGUOUS);
    if (arr == NULL) return NULL;

    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1)) {
        PyErr_SetString(PyExc_ValueError, "expected a square 2-D array");
        Py_DECREF(arr);
        return NULL;
    }
    npy_intp npy_n = PyArray_DIM(arr, 0);
    int n = (int)npy_n;
    if (n < 1 || n > 256) {
        PyErr_SetString(PyExc_ValueError, "matrix size out of range");
        Py_DECREF(arr);
        return NULL;
    }

    double a_stack[256 * 256];
    double vr_stack[256 * 256];
    double wr_stack[256], wi_stack[256], work_stack[4096];
    double *a = a_stack, *vr = vr_stack, *wr = wr_stack, *wi = wi_stack,
           *work = work_stack;
    double *heap = NULL;
    if (n > 64) {
        size_t nn = (size_t)n * (size_t)n;
        heap = (double *)malloc((2 * nn + 2 * (size_t)n + 4096) * sizeof(double));
        if (heap == NULL) {
            Py_DECREF(arr);
            return PyErr_NoMemory();
        }
        a = heap;
        vr = a + nn;
        wr = vr + nn;
        wi = wr + n;
        work = wi + n;
    }

    const double *src = (const double *)PyArray_DATA(arr);
    npy_intp s0 = PyArray_STRIDE(arr, 0) / (npy_intp)sizeof(double);
    npy_intp s1 = PyArray_STRIDE(arr, 1) / (npy_intp)sizeof(double);
    /* Copy into column-major storage required by LAPACK. */
    for (int j = 0; j < n; ++j) {
        double *dst = a + (size_t)j * n;
        const double *p = src + (size_t)j * s1;
        for (int i = 0; i < n; ++i) dst[i] = p[(size_t)i * s0];
    }
    Py_DECREF(arr);

    char jobvl = 'N', jobvr = 'V';
    int lda = n, ldvl = 1, ldvr = n, lwork = 4096, info = 0;
    double vl_dummy[1];

    dgeev_(&jobvl, &jobvr, &n, a, &lda, wr, wi, vl_dummy, &ldvl, vr, &ldvr,
           work, &lwork, &info, (size_t)1, (size_t)1);

    if (info != 0) {
        if (heap) free(heap);
        PyErr_SetString(PyExc_RuntimeError, "LAPACK dgeev failed");
        return NULL;
    }

    int idx = 0;
    double best = wr[0] * wr[0] + wi[0] * wi[0];
    for (int i = 1; i < n; ++i) {
        double mag = wr[i] * wr[i] + wi[i] * wi[i];
        if (mag > best) { best = mag; idx = i; }
    }

    PyObject *val, *vec;
    npy_intp dims[1] = {(npy_intp)n};
    if (wi[idx] == 0.0) {
        val = PyFloat_FromDouble(wr[idx]);
        vec = PyArray_SimpleNew(1, dims, NPY_DOUBLE);
        if (!val || !vec) goto fail;
        double *out = (double *)PyArray_DATA((PyArrayObject *)vec);
        const double *col = vr + (size_t)idx * n;
        for (int i = 0; i < n; ++i) out[i] = col[i];
    } else {
        double im = wi[idx];
        if (im > 0.0) {
            val = PyComplex_FromDoubles(wr[idx], im);
            vec = PyArray_SimpleNew(1, dims, NPY_CDOUBLE);
            if (!val || !vec) goto fail;
            npy_cdouble *out = (npy_cdouble *)PyArray_DATA((PyArrayObject *)vec);
            const double *re = vr + (size_t)idx * n;
            const double *ii = vr + (size_t)(idx + 1) * n;
            for (int i = 0; i < n; ++i)
                out[i] = npy_cpack(re[i], ii[i]);
        } else {
            val = PyComplex_FromDoubles(wr[idx], im);
            vec = PyArray_SimpleNew(1, dims, NPY_CDOUBLE);
            if (!val || !vec) goto fail;
            npy_cdouble *out = (npy_cdouble *)PyArray_DATA((PyArrayObject *)vec);
            const double *re = vr + (size_t)(idx - 1) * n;
            const double *ii = vr + (size_t)idx * n;
            for (int i = 0; i < n; ++i)
                out[i] = npy_cpack(re[i], -ii[i]);
        }
    }
    if (heap) free(heap);
    {
        PyObject *ret = PyTuple_Pack(2, val, vec);
        Py_DECREF(val);
        Py_DECREF(vec);
        return ret;
    }

fail:
    if (heap) free(heap);
    Py_XDECREF(val);
    Py_XDECREF(vec);
    return NULL;
}

static PyMethodDef methods[] = {
    {"dominant_eigen", dominant_eigen, METH_O, "Dominant eigenpair via LAPACK."},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigen_fast", NULL, -1, methods
};

PyMODINIT_FUNC
PyInit__eigen_fast(void)
{
    import_array();
    return PyModule_Create(&moduledef);
}
