#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <dlfcn.h>

typedef void (*dgeev_i32_fn)(char *, char *, int32_t *, double *, int32_t *,
                             double *, double *, double *, int32_t *,
                             double *, int32_t *, double *, int32_t *,
                             int32_t *, size_t, size_t);
typedef void (*dgeev_i64_fn)(char *, char *, int64_t *, double *, int64_t *,
                             double *, double *, double *, int64_t *,
                             double *, int64_t *, double *, int64_t *,
                             int64_t *, size_t, size_t);

static dgeev_i32_fn dgeev_i32 = NULL;
static dgeev_i64_fn dgeev_i64 = NULL;
static int lapack_loaded = 0;

static int
load_symbols_from(void *handle)
{
    if (dgeev_i64 == NULL) {
        dgeev_i64 = (dgeev_i64_fn)dlsym(handle, "scipy_dgeev_64_");
        if (dgeev_i64 == NULL)
            dgeev_i64 = (dgeev_i64_fn)dlsym(handle, "dgeev_64_");
    }
    if (dgeev_i32 == NULL)
        dgeev_i32 = (dgeev_i32_fn)dlsym(handle, "dgeev_");
    return (dgeev_i32 != NULL || dgeev_i64 != NULL);
}

static int
load_lapack(void)
{
    if (lapack_loaded) return (dgeev_i32 != NULL || dgeev_i64 != NULL);
    lapack_loaded = 1;

    /* First use a system LAPACK/OpenBLAS if one is available. */
    const char *names[] = {
        "liblapack.so.3", "liblapack.so", "libopenblas.so.0",
        "libopenblas.so", NULL
    };
    for (int i = 0; names[i] != NULL; ++i) {
        void *h = dlopen(names[i], RTLD_NOW | RTLD_LOCAL);
        if (h != NULL && load_symbols_from(h)) return 1;
    }

    /* numpy ships an OpenBLAS build under a hashed name.  It is already
       mapped into this process after importing numpy; locate it in maps. */
    FILE *fp = fopen("/proc/self/maps", "r");
    if (fp != NULL) {
        char line[4096];
        while (fgets(line, sizeof(line), fp) != NULL) {
            if (strstr(line, "openblas") == NULL &&
                strstr(line, "OpenBLAS") == NULL)
                continue;
            char *path = strchr(line, '/');
            if (path == NULL) continue;
            char *nl = strchr(path, '\n');
            if (nl) *nl = '\0';
            void *h = dlopen(path, RTLD_NOW | RTLD_LOCAL);
            if (h != NULL && load_symbols_from(h)) {
                fclose(fp);
                return 1;
            }
        }
        fclose(fp);
    }
    return (dgeev_i32 != NULL || dgeev_i64 != NULL);
}

static int
call_dgeev(int n, double *a, double *wr, double *wi, double *vr,
           double *work, int lwork)
{
    char jobvl = 'N', jobvr = 'V';
    double vl_dummy[1];
    if (dgeev_i64 != NULL) {
        int64_t n64 = n, lda = n, ldvl = 1, ldvr = n, lwork64 = lwork,
                info = 0;
        dgeev_i64(&jobvl, &jobvr, &n64, a, &lda, wr, wi, vl_dummy, &ldvl,
                  vr, &ldvr, work, &lwork64, &info, (size_t)1, (size_t)1);
        return (int)info;
    }
    if (dgeev_i32 != NULL) {
        int32_t n32 = n, lda = n, ldvl = 1, ldvr = n, lwork32 = lwork,
                info = 0;
        dgeev_i32(&jobvl, &jobvr, &n32, a, &lda, wr, wi, vl_dummy, &ldvl,
                  vr, &ldvr, work, &lwork32, &info, (size_t)1, (size_t)1);
        return (int)info;
    }
    return -999;
}

static PyObject *
dominant_eigen(PyObject *self, PyObject *arg)
{
    if (!lapack_loaded && !load_lapack()) {
        PyErr_SetString(PyExc_ImportError, "could not load a LAPACK dgeev");
        return NULL;
    }

    PyArrayObject *arr = (PyArrayObject *)PyArray_FROM_OTF(
        arg, NPY_DOUBLE, NPY_ARRAY_ALIGNED | NPY_ARRAY_C_CONTIGUOUS);
    if (arr == NULL) return NULL;

    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1)) {
        PyErr_SetString(PyExc_ValueError, "expected a square 2-D array");
        Py_DECREF(arr);
        return NULL;
    }
    npy_intp npy_n = PyArray_DIM(arr, 0);
    if (npy_n < 1 || npy_n > 100000) {
        PyErr_SetString(PyExc_ValueError, "matrix size out of range");
        Py_DECREF(arr);
        return NULL;
    }
    int n = (int)npy_n;

    double a_stack[64 * 64];
    double vr_stack[64 * 64];
    double wr_stack[64], wi_stack[64], work_stack[4096];
    double *a = a_stack, *vr = vr_stack, *wr = wr_stack, *wi = wi_stack,
           *work = work_stack;
    double *heap = NULL;
    if (n > 64) {
        size_t nn = (size_t)n * (size_t)n;
        heap = (double *)malloc((2 * nn + 2 * (size_t)n + 4096) * sizeof(double));
        if (heap == NULL) {
            Py_DECREF(arr);
            return PyErr_NoMemory();
        }
        a = heap;
        vr = a + nn;
        wr = vr + nn;
        wi = wr + n;
        work = wi + n;
    }

    const double *src = (const double *)PyArray_DATA(arr);
    npy_intp s0 = PyArray_STRIDE(arr, 0) / (npy_intp)sizeof(double);
    npy_intp s1 = PyArray_STRIDE(arr, 1) / (npy_intp)sizeof(double);
    /* LAPACK needs column-major input. */
    for (int j = 0; j < n; ++j) {
        double *dst = a + (size_t)j * n;
        const double *p = src + (size_t)j * s1;
        for (int i = 0; i < n; ++i) dst[i] = p[(size_t)i * s0];
    }
    Py_DECREF(arr);

    int info = call_dgeev(n, a, wr, wi, vr, work, 4096);
    if (info != 0) {
        if (heap) free(heap);
        if (info == -999)
            PyErr_SetString(PyExc_ImportError, "no LAPACK dgeev available");
        else
            PyErr_SetString(PyExc_RuntimeError, "LAPACK dgeev failed");
        return NULL;
    }

    int idx = 0;
    double best = wr[0] * wr[0] + wi[0] * wi[0];
    for (int i = 1; i < n; ++i) {
        double mag = wr[i] * wr[i] + wi[i] * wi[i];
        if (mag > best) { best = mag; idx = i; }
    }

    PyObject *val, *vec;
    npy_intp dims[1] = {(npy_intp)n};
    if (wi[idx] == 0.0) {
        val = PyFloat_FromDouble(wr[idx]);
        vec = PyArray_SimpleNew(1, dims, NPY_DOUBLE);
        if (!val || !vec) goto fail;
        double *out = (double *)PyArray_DATA((PyArrayObject *)vec);
        const double *col = vr + (size_t)idx * n;
        for (int i = 0; i < n; ++i) out[i] = col[i];
    } else {
        double im = wi[idx];
        val = PyComplex_FromDoubles(wr[idx], im);
        vec = PyArray_SimpleNew(1, dims, NPY_CDOUBLE);
        if (!val || !vec) goto fail;
        double *out = (double *)PyArray_DATA((PyArrayObject *)vec);
        if (im > 0.0) {
            const double *re = vr + (size_t)idx * n;
            const double *ii = vr + (size_t)(idx + 1) * n;
            for (int i = 0; i < n; ++i) {
                out[2 * i] = re[i];
                out[2 * i + 1] = ii[i];
            }
        } else {
            const double *re = vr + (size_t)(idx - 1) * n;
            const double *ii = vr + (size_t)idx * n;
            for (int i = 0; i < n; ++i) {
                out[2 * i] = re[i];
                out[2 * i + 1] = -ii[i];
            }
        }
    }
    if (heap) free(heap);
    {
        PyObject *ret = PyTuple_Pack(2, val, vec);
        Py_DECREF(val);
        Py_DECREF(vec);
        return ret;
    }

fail:
    if (heap) free(heap);
    Py_XDECREF(val);
    Py_XDECREF(vec);
    return NULL;
}

